-- Contract attachment samples are explicitly marked as demo data.
-- Spreadsheet previews are stored as structured sheet data; PDFs/images contain real file bytes.
create table contract_attachments (
    id varchar(64) primary key,
    contract_id varchar(64) not null references contracts(id),
    name varchar(255) not null,
    document_type varchar(64) not null,
    resource varchar(255) not null,
    document_date varchar(10) not null,
    uploader varchar(64) not null,
    uploaded_at varchar(32) not null,
    file_size varchar(32) not null,
    status varchar(32) not null,
    format varchar(32) not null check (format in ('SPREADSHEET', 'PDF', 'IMAGE')),
    mime_type varchar(128) not null,
    preview_json text,
    file_base64 text,
    is_demo boolean not null default false
);
create index idx_contract_attachments_contract on contract_attachments(contract_id, uploaded_at);

